// ---------------------------------------------------------------------------
// Enneagramm-Memory: Merkspiel auf Basis der Porträt-Fotos. Zieht automatisch
// aus allen Porträt-Registern (musterradarAllPortraits()) – jedes neue
// Porträt vergrößert damit von selbst den Kartenpool, keine manuelle Pflege
// nötig. Drei Schwierigkeitsstufen (level 1/2/3), die definieren, wie fein
// ein "Paar" erkannt werden muss:
//   Level 1 (Anfänger):      nur der Grundtyp (1–9) muss übereinstimmen
//   Level 2 (Fortgeschritten): Grundtyp + Flügel müssen übereinstimmen
//   Level 3 (Experte):       vollständiger Subtyp (Instinkt+Typ+Flügel)
// Getippt wird rein nach Gesicht/Blickqualität, kein Name während der
// Merkphase sichtbar. Nach jeder Rundenauflösung lassen sich alle neun
// Karten der Runde antippen, um Name + Typ jeder einzelnen Person zu sehen.
// ---------------------------------------------------------------------------

const MEMORY_TOTAL_ROUNDS = 10;
const MEMORY_MEMORIZE_MS = 60000;
const MEMORY_LEVEL_META = {
  1: { label: "Enneagramm-Memory I", sub: "Anfänger · nur der Grundtyp zählt",
       rule: "Zwei Karten bilden ein Paar, wenn sie zum selben <strong>Grundtyp (1&ndash;9)</strong> gehören &ndash; Instinktvariante und Flügel spielen keine Rolle. Beispiel: <strong>SO3</strong> und <strong>SX3</strong> zählen als Paar, weil beide Typ 3 sind." },
  2: { label: "Enneagramm-Memory II", sub: "Fortgeschrittene · Grundtyp + Flügel",
       rule: "Zwei Karten bilden ein Paar, wenn <strong>Grundtyp UND Flügel</strong> übereinstimmen &ndash; die Instinktvariante (SE/SO/SX) spielt keine Rolle. Beispiel: <strong>SE4w3</strong> und <strong>SX4w3</strong> zählen als Paar, weil beide 4w3 sind." },
  3: { label: "Enneagramm-Memory III", sub: "Experte · vollständiger Subtyp (Instinkt+Typ+Flügel)",
       rule: "Zwei Karten bilden nur dann ein Paar, wenn der <strong>komplette Subtyp inklusive Instinktvariante und Flügel</strong> exakt übereinstimmt. Beispiel: Nur zwei Porträts mit exakt <strong>SO1w9</strong> bilden ein Paar &ndash; SE1w9 zählt nicht dazu." },
};

let _memoryState = null;
let _memoryLastLevel = 1;
const _memoryImgCache = {};

function _memoryImgFor(route) {
  if (_memoryImgCache[route] !== undefined) return _memoryImgCache[route];
  let src = null;
  try {
    const fn = ROUTES[route];
    if (fn) {
      const html = fn();
      const m = html.match(/<img\s+src="([^"]+)"[^>]*class="krim-portrait-img"/);
      if (m) src = m[1];
    }
  } catch (e) {}
  _memoryImgCache[route] = src;
  return src;
}

const _memoryImgValidCache = {};
function _memoryValidateImg(src) {
  if (_memoryImgValidCache[src] !== undefined) return Promise.resolve(_memoryImgValidCache[src]);
  return new Promise(resolve => {
    const img = new Image();
    img.onload = () => { _memoryImgValidCache[src] = true; resolve(true); };
    img.onerror = () => { _memoryImgValidCache[src] = false; resolve(false); };
    img.src = src;
  });
}

function _memoryGroupKey(subtyp, level) {
  const p = musterradarParseSubtyp(subtyp);
  if (!p) return null;
  if (level === 1) return "T" + p.typ;
  if (level === 2) return p.wing ? ("T" + p.typ + "W" + p.wing) : null;
  return p.instinct + p.typ + (p.wing ? "W" + p.wing : "");
}

function _memoryCardLabel(subtyp, level) {
  const p = musterradarParseSubtyp(subtyp);
  if (!p) return (subtyp || "").toUpperCase();
  if (level === 1) return "Typ " + p.typ;
  if (level === 2) return p.typ + (p.wing ? "w" + p.wing : "");
  return (subtyp || "").toUpperCase();
}

function _memoryBuildPools(level) {
  const all = [...BERUEHMT_PORTRAITS, ...KRIMINAL_PORTRAITS].filter(p => p.subtyp && p.route);
  const byKey = {};
  all.forEach(p => {
    const key = _memoryGroupKey(p.subtyp, level);
    if (!key) return;
    (byKey[key] = byKey[key] || []).push(p);
  });
  return byKey;
}

function _memoryShuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

async function _memoryFindValidPortrait(candidates, usedRoutes) {
  for (const p of candidates) {
    if (usedRoutes.has(p.route)) continue;
    const img = _memoryImgFor(p.route);
    if (!img) continue;
    const ok = await _memoryValidateImg(img);
    if (ok) return { route: p.route, subtyp: p.subtyp, name: p.name, img };
  }
  return null;
}

async function _memoryPickRound(level) {
  const pools = _memoryBuildPools(level);
  const pairKeys = _memoryShuffle(Object.keys(pools).filter(c => pools[c].length >= 2));
  if (!pairKeys.length) return null;

  // Jedes Foto wird vorab geladen und geprüft – nur bestätigt funktionierende
  // Bilder landen auf einer Karte. Klappt ein Paar oder genug Distraktoren mit
  // dem gewählten Schlüssel nicht, wird der nächste Schlüssel probiert.
  for (const pairKey of pairKeys) {
    const usedRoutes = new Set();
    const pairShuffled = _memoryShuffle(pools[pairKey]);
    const validPair = [];
    for (const p of pairShuffled) {
      if (validPair.length >= 2) break;
      const found = await _memoryFindValidPortrait([p], usedRoutes);
      if (found) { validPair.push(found); usedRoutes.add(found.route); }
    }
    if (validPair.length < 2) continue;

    const otherKeys = _memoryShuffle(Object.keys(pools).filter(c => c !== pairKey));
    const distractors = [];
    for (const key of otherKeys) {
      if (distractors.length >= 7) break;
      const found = await _memoryFindValidPortrait(_memoryShuffle(pools[key]), usedRoutes);
      if (found) { distractors.push(found); usedRoutes.add(found.route); }
    }
    if (distractors.length < 7) continue;

    const cards = _memoryShuffle([...validPair, ...distractors]).slice(0, 9);
    const pairRoutes = new Set(validPair.map(p => p.route));
    return { cards, pairRoutes, pairKey };
  }
  return null;
}

function _memoryRerender() {
  if (location.hash === "#enneagramm-memory") { render(); } else { location.hash = "enneagramm-memory"; }
}

function _memoryBestKey(level) { return "kompass:memoryBest:" + level; }

function _memorySaveBest(level, score) {
  try {
    const prev = parseInt(localStorage.getItem(_memoryBestKey(level)) || "0", 10);
    if (score > prev) localStorage.setItem(_memoryBestKey(level), String(score));
  } catch (e) {}
}

function _memoryGetBest(level) {
  try { return parseInt(localStorage.getItem(_memoryBestKey(level)) || "0", 10); } catch (e) { return 0; }
}

async function _memoryNextRound() {
  const st = _memoryState;
  if (!st) return;
  st.round += 1;
  if (st.round > MEMORY_TOTAL_ROUNDS) {
    st.phase = "gameOver";
    _memorySaveBest(st.level, st.score);
    _memoryRerender();
    return;
  }
  st.phase = "roundLoading";
  _memoryRerender();
  const roundData = await _memoryPickRound(st.level);
  if (_memoryState !== st) return; // Spiel wurde inzwischen neu gestartet/verlassen
  if (!roundData) { st.phase = "gameOver"; _memoryRerender(); return; }
  st.cards = roundData.cards;
  st.pairRoutes = roundData.pairRoutes;
  st.selected = [];
  st.revealed = [];
  st.resolution = null;
  st.phase = "memorize";
  _memoryRerender();
  if (st._timer) clearTimeout(st._timer);
  st._timer = setTimeout(() => {
    if (_memoryState === st && st.phase === "memorize") {
      st.phase = "guess";
      _memoryRerender();
    }
  }, MEMORY_MEMORIZE_MS);
}

window._memoryStart = function (level) {
  const lvl = MEMORY_LEVEL_META[level] ? level : 1;
  _memoryLastLevel = lvl;
  _memoryState = { level: lvl, phase: "loading", round: 0, score: 0, cards: [], pairRoutes: new Set(), selected: [], revealed: [], resolution: null };
  _memoryNextRound();
};

window._memorySwitchLevel = function (level) {
  const lvl = MEMORY_LEVEL_META[level] ? level : 1;
  _memoryLastLevel = lvl;
  _memoryState = null;
  _memoryRerender();
};

window._memoryPick = function (idx) {
  const st = _memoryState;
  if (!st || st.phase !== "guess") return;
  if (st.selected.includes(idx)) {
    st.selected = st.selected.filter(i => i !== idx);
    _memoryRerender();
    return;
  }
  if (st.selected.length >= 2) return;
  st.selected.push(idx);
  if (st.selected.length === 2) {
    const [a, b] = st.selected;
    const correct = st.pairRoutes.has(st.cards[a].route) && st.pairRoutes.has(st.cards[b].route);
    const correctIdxs = st.cards.map((c, i) => st.pairRoutes.has(c.route) ? i : -1).filter(i => i >= 0);
    st.resolution = { correct, correctIdxs };
    if (correct) st.score += 1;
    st.phase = "roundResult";
    if (st._timer) clearTimeout(st._timer);
  }
  _memoryRerender();
};

window._memoryReveal = function (idx) {
  const st = _memoryState;
  if (!st || st.phase !== "roundResult") return;
  if (!st.revealed.includes(idx)) {
    st.revealed = [...st.revealed, idx];
    _memoryRerender();
  }
};

window._memoryNextRound = function () { _memoryNextRound(); };
window._memoryRestart = function () {
  const lvl = _memoryState ? _memoryState.level : 1;
  window._memoryStart(lvl);
};

function _memoryCardHtml(card, i, st) {
  const isMemorize = st.phase === "memorize";
  const isSelected = st.selected.includes(i);
  const isResult = st.phase === "roundResult";
  const isCorrectCard = isResult && st.resolution.correctIdxs.includes(i);
  const isWrongPick = isResult && st.selected.includes(i) && !isCorrectCard;
  const isRevealed = isResult && st.revealed.includes(i);
  const open = isMemorize || isSelected || isCorrectCard || isRevealed;
  let stateClass = "";
  if (isResult) {
    if (isCorrectCard) stateClass = " mem-card--correct";
    else if (isWrongPick) stateClass = " mem-card--wrong";
  } else if (isSelected) {
    stateClass = " mem-card--selected";
  }
  const clickable = st.phase === "guess" || (isResult && !open);
  let onclick = "";
  if (st.phase === "guess") onclick = ` onclick="window._memoryPick(${i})"`;
  else if (isResult && !open) onclick = ` onclick="window._memoryReveal(${i})"`;
  const caption = (isResult && open)
    ? `<div class="mem-card-caption">${card.name} &middot; ${_memoryCardLabel(card.subtyp, st.level)}</div>`
    : "";
  return `
    <div class="mem-card${open ? " mem-card--open" : ""}${stateClass}"${onclick} role="button" aria-label="Karte ${i + 1}">
      <div class="mem-card-inner">
        <div class="mem-card-face mem-card-face--back">
          <span class="mem-card-mark">✦</span>
        </div>
        <div class="mem-card-face mem-card-face--front">
          <img src="${card.img}" alt="" loading="lazy" onerror="this.closest('.mem-card').classList.add('mem-card--broken');this.style.display='none';" />
          ${caption}
        </div>
      </div>
    </div>
  `;
}

function _memoryLevelSwitcher(currentLevel) {
  const items = [1,2,3].map(l => {
    const active = l === currentLevel;
    return active
      ? `<span class="mem-level-pill mem-level-pill--active">${l===1?"I":l===2?"II":"III"}</span>`
      : `<a href="javascript:void(0)" class="mem-level-pill" onclick="window._memorySwitchLevel(${l})">${l===1?"I":l===2?"II":"III"}</a>`;
  }).join("");
  return `<div class="mem-level-switcher"><span class="mem-level-switcher-label">Stufe:</span>${items}</div>`;
}

function _memoryStyles() {
  return `
    <style>
      .mem-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:0.7rem; max-width:420px; margin:1.2rem auto; }
      .mem-card { aspect-ratio:1/1; perspective:900px; cursor:default; }
      .mem-card[role="button"] { cursor:pointer; }
      .mem-card-inner { position:relative; width:100%; height:100%; transform-style:preserve-3d; transition:transform .5s cubic-bezier(.4,.2,.2,1); border-radius:12px; }
      .mem-card--open .mem-card-inner { transform:rotateY(180deg); }
      .mem-card-face { position:absolute; inset:0; backface-visibility:hidden; border-radius:12px; overflow:hidden; display:flex; align-items:center; justify-content:center; }
      .mem-card-face--back { background:linear-gradient(135deg, var(--copper,#a5603d), #6d3e26); animation:memBackIn .65s ease-out; }
      .mem-card-mark { color:rgba(255,255,255,0.55); font-size:1.4rem; }
      .mem-card-face--front { transform:rotateY(180deg); background:var(--card,var(--paper)); border:2px solid var(--line,var(--border)); }
      .mem-card-face--front img { width:100%; height:100%; object-fit:cover; filter:blur(0); transition:filter .3s; }
      .mem-card--open .mem-card-face--front img { animation:memPhotoIn .7s ease-out; }
      @keyframes memBackIn { 0%{ filter:blur(8px); opacity:.3; } 100%{ filter:blur(0); opacity:1; } }
      @keyframes memPhotoIn { 0%{ filter:blur(13px); opacity:.2; } 100%{ filter:blur(0); opacity:1; } }
      .mem-card--selected .mem-card-face--back { box-shadow:0 0 0 3px var(--copper,#a5603d) inset; }
      .mem-card--correct .mem-card-face--front { border-color:#3a9552; box-shadow:0 0 0 3px #3a9552; }
      .mem-card--wrong .mem-card-face--front { border-color:#c0392b; box-shadow:0 0 0 3px #c0392b; }
      .mem-card--broken .mem-card-face--front { background:var(--line,var(--border)); }
      .mem-card--broken .mem-card-face--front::before { content:"🧩"; font-size:1.8rem; opacity:0.5; }
      .mem-card-caption { position:absolute; left:0; right:0; bottom:0; background:rgba(20,17,12,0.72); color:#fff; font-size:0.62rem; line-height:1.25; text-align:center; padding:0.25rem 0.2rem; }
      .mem-progress-wrap { height:5px; background:var(--line,var(--border)); border-radius:3px; overflow:hidden; max-width:420px; margin:0 auto 0.9rem; }
      .mem-progress-bar { height:100%; background:var(--copper,#a5603d); width:100%; transform-origin:left; animation:memShrink ${MEMORY_MEMORIZE_MS}ms linear forwards; }
      @keyframes memShrink { from{ transform:scaleX(1); } to{ transform:scaleX(0); } }
      .mem-hud { display:flex; justify-content:space-between; align-items:baseline; max-width:420px; margin:0 auto 0.6rem; font-size:0.85rem; color:var(--muted); }
      .mem-hud strong { color:var(--ink); }
      .mem-resolution { max-width:420px; margin:1rem auto 0; text-align:center; }
      .mem-resolution p { margin:0 0 0.9rem; font-size:0.95rem; }
      .mem-pair-reveal { background:var(--card,var(--paper)); border:1px solid var(--line,var(--border)); border-radius:10px; padding:0.7rem 1rem; margin:0 0 1rem; }
      .mem-pair-reveal-label { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.05em; color:var(--muted); font-weight:600; margin:0 0 0.3rem; }
      .mem-pair-reveal p:last-child { margin:0; font-size:0.95rem; }
      .mem-explore-hint { font-size:0.78rem; color:var(--muted); text-align:center; margin:0.6rem 0 0; }
      .mem-btn { background:var(--copper,#a5603d); color:#fff; border:none; padding:0.75rem 2rem; border-radius:24px; font-size:0.95rem; font-family:inherit; cursor:pointer; font-weight:600; }
      .mem-level-picker { display:flex; flex-direction:column; gap:0.7rem; max-width:420px; margin:0 auto 1.6rem; }
      .mem-level-card { display:block; width:100%; text-align:left; background:var(--card,var(--paper)); border:1px solid var(--line,var(--border)); border-radius:12px; padding:0.9rem 1.1rem; cursor:pointer; font-family:inherit; }
      .mem-level-card:hover { border-color:var(--copper); }
      .mem-level-switcher { display:flex; align-items:center; justify-content:center; gap:0.4rem; max-width:420px; margin:0 auto 0.8rem; font-size:0.8rem; }
      .mem-level-switcher-label { color:var(--muted); margin-right:0.2rem; }
      .mem-level-pill { display:inline-flex; align-items:center; justify-content:center; min-width:1.8rem; padding:0.2rem 0.5rem; border-radius:99px; border:1.5px solid var(--line,var(--border)); color:var(--muted); text-decoration:none; font-weight:600; cursor:pointer; }
      .mem-level-pill:hover { border-color:var(--copper); color:var(--copper); }
      .mem-level-pill--active { background:var(--copper,#a5603d); border-color:var(--copper,#a5603d); color:#fff; cursor:default; }
      .mem-rule-box { background:color-mix(in srgb, var(--copper) 8%, var(--paper)); border:1px solid var(--copper); border-radius:12px; padding:1rem 1.2rem; margin:0 0 1.4rem; font-size:0.9rem; line-height:1.55; }
      .mem-rule-box-label { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.05em; color:var(--copper); font-weight:700; margin:0 0 0.4rem; }
      .mem-level-card strong { display:block; font-size:1rem; color:var(--ink); margin-bottom:0.15rem; }
      .mem-level-card span { font-size:0.82rem; color:var(--muted); }
    </style>
  `;
}

function _memoryIntroScreen(level) {
  const meta = MEMORY_LEVEL_META[level];
  const best = _memoryGetBest(level);
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_memoryLevelSwitcher(level)}
        <p class="psycho-intro">Neun Porträtfotos werden aufgedeckt &ndash; genau zwei davon bilden ein Paar. Merken Sie sich die Gesichter, nicht die Namen: Es geht rein um die Blickqualität. Nach ${MEMORY_MEMORIZE_MS / 1000} Sekunden werden die Karten verdeckt, und Sie müssen aus dem Gedächtnis das richtige Paar anklicken. 10 Runden pro Durchgang &ndash; nach jeder Runde dürfen Sie zusätzlich alle neun Karten antippen, um Name und Typ jeder Person zu sehen.</p>
        <div class="mem-rule-box">
          <p class="mem-rule-box-label">Was zählt in dieser Stufe als Paar?</p>
          <p style="margin:0;">${meta.rule}</p>
        </div>
        <div style="background:var(--card,var(--paper));border:1px solid var(--line,var(--border));border-left:4px solid var(--copper);border-radius:12px;padding:1rem 1.2rem;margin:0 0 1.6rem;font-size:.9rem;">
          Die Karten stammen aus allen über 600 Porträts des Kompasses &ndash; Berühmte Persönlichkeiten, Kriminalpsychologie und Krankheitsporträts gemischt. Je mehr Porträts hinzukommen, desto größer wird der Kartenpool automatisch.
        </div>
        ${best > 0 ? `<p style="text-align:center;color:var(--muted);font-size:0.9rem;margin-bottom:1.2rem;">Ihre Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${MEMORY_TOTAL_ROUNDS}</strong></p>` : ""}
        <div style="text-align:center;">
          <button class="mem-btn" onclick="window._memoryStart(${level})">Spiel starten &rarr;</button>
        </div>
      </div>
      ${_memoryStyles()}
    </div>
  `);
}

function _memoryGameScreen() {
  const st = _memoryState;
  const meta = MEMORY_LEVEL_META[st.level];
  const cardsHtml = st.cards.map((c, i) => _memoryCardHtml(c, i, st)).join("");
  const showProgress = st.phase === "memorize";
  let footer = "";
  if (st.phase === "memorize") {
    footer = `<p style="text-align:center;color:var(--muted);font-size:0.85rem;">Merken Sie sich die Gesichter &ndash; gleich werden die Karten verdeckt …</p>`;
  } else if (st.phase === "guess") {
    footer = `<p style="text-align:center;color:var(--muted);font-size:0.85rem;">Klicken Sie die zwei Karten, die ein Paar bilden.</p>`;
  } else if (st.phase === "roundResult") {
    const msg = st.resolution.correct
      ? "Richtig erkannt!"
      : "Leider daneben &ndash; das eigentliche Paar ist grün markiert.";
    const isLast = st.round >= MEMORY_TOTAL_ROUNDS;
    const [pairA, pairB] = st.resolution.correctIdxs.map(i => st.cards[i]);
    const pairReveal = pairA && pairB ? `
      <div class="mem-pair-reveal">
        <p class="mem-pair-reveal-label">Das Paar &ndash; beide ${_memoryCardLabel(pairA.subtyp, st.level)}:</p>
        <p><strong>${pairA.name}</strong> &amp; <strong>${pairB.name}</strong></p>
      </div>
    ` : "";
    footer = `
      <div class="mem-resolution">
        <p><strong>${msg}</strong></p>
        ${pairReveal}
        <p class="mem-explore-hint">Tippen Sie auf die übrigen Karten, um zu sehen, wer sie sind.</p>
        <button class="mem-btn" onclick="window._memoryNextRound()">${isLast ? "Endergebnis &rarr;" : "Nächste Runde &rarr;"}</button>
      </div>
    `;
  }
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_memoryLevelSwitcher(st.level)}
        <div class="mem-hud">
          <span>Runde <strong>${st.round}</strong> / ${MEMORY_TOTAL_ROUNDS}</span>
          <span>Punkte: <strong>${st.score}</strong></span>
        </div>
        ${showProgress ? `<div class="mem-progress-wrap"><div class="mem-progress-bar"></div></div>` : ""}
        <div class="mem-grid">${cardsHtml}</div>
        ${footer}
      </div>
      ${_memoryStyles()}
    </div>
  `);
}

function _memoryGameOverScreen() {
  const st = _memoryState;
  const meta = MEMORY_LEVEL_META[st.level];
  const best = _memoryGetBest(st.level);
  const pct = Math.round((st.score / MEMORY_TOTAL_ROUNDS) * 100);
  let msg;
  if (pct >= 90) msg = "Außergewöhnlich &ndash; ein sehr geschulter Blick für Blickqualitäten!";
  else if (pct >= 70) msg = "Sehr gut! Die Gesichter der Subtypen prägen sich bei Ihnen schon deutlich ein.";
  else if (pct >= 40) msg = "Solide Runde &ndash; mit mehr Übung wird der Blick noch sicherer.";
  else msg = "Ein Anfang &ndash; das Erkennen von Blickqualitäten braucht Übung. Nochmal versuchen?";
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${st.score} von ${MEMORY_TOTAL_ROUNDS} richtig</h1>
        ${_memoryLevelSwitcher(st.level)}
        <p style="color:var(--muted);margin:0 0 0.8rem;">${pct}&thinsp;%</p>
        <p style="max-width:420px;margin:0 auto 1rem;">${msg}</p>
        <p style="color:var(--muted);font-size:0.9rem;margin-bottom:2rem;">Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${MEMORY_TOTAL_ROUNDS}</strong></p>
        <button class="mem-btn" onclick="window._memoryRestart()">Neue Runde &rarr;</button>
      </div>
      ${_memoryStyles()}
    </div>
  `);
}

function _enneagrammMemoryLevelPage(level) {
  if (!_memoryState || _memoryState.level !== level || _memoryState.phase === "loading") return _memoryIntroScreen(level);
  if (_memoryState.phase === "roundLoading") return _memoryRoundLoadingScreen();
  if (_memoryState.phase === "gameOver") return _memoryGameOverScreen();
  return _memoryGameScreen();
}

function enneagrammMemoryPage() {
  const level = _memoryState ? _memoryState.level : _memoryLastLevel;
  return _enneagrammMemoryLevelPage(level);
}

function _memoryRoundLoadingScreen() {
  const st = _memoryState;
  const meta = MEMORY_LEVEL_META[st.level];
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;padding-top:3rem;padding-bottom:5rem;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        <p style="color:var(--muted);margin-top:1.5rem;">Runde wird vorbereitet …</p>
      </div>
    </div>
  `);
}

function enneagrammMemory1Page() { return _enneagrammMemoryLevelPage(1); }
function enneagrammMemory2Page() { return _enneagrammMemoryLevelPage(2); }
function enneagrammMemory3Page() { return _enneagrammMemoryLevelPage(3); }


// ---------------------------------------------------------------------------
// Enneagramm-Flashcards: Multiple-Choice-Trainer, Ableger von Enneagramm-Memory.
// Ein Porträtfoto wird gezeigt, vier Antwortmöglichkeiten stehen zur Wahl –
// nur eine ist richtig. Nutzt dieselbe Bildpool-/Validierungs-Infrastruktur
// und dieselben drei Granularitätsstufen wie Enneagramm-Memory (Grundtyp /
// Grundtyp+Flügel / voller Subtyp), aber als reines Wiedererkennungstraining
// statt Paare-Finden. 10 Fragen pro Runde, Bestleistung je Stufe gespeichert.
// ---------------------------------------------------------------------------

const FLASH_TOTAL_ROUNDS = 10;
const FLASH_LEVEL_META = {
  1: { label: "Enneagramm-Flashcards I", sub: "Anfänger · nur der Grundtyp zählt",
       rule: "Sie sehen ein Porträtfoto und vier Antwortmöglichkeiten, jede ein <strong>Grundtyp (1&ndash;9)</strong>. Gefragt ist nur der Grundtyp der Person &ndash; Instinktvariante und Flügel spielen keine Rolle." },
  2: { label: "Enneagramm-Flashcards II", sub: "Fortgeschrittene · Grundtyp + Flügel",
       rule: "Sie sehen ein Porträtfoto und vier Antwortmöglichkeiten, jede eine Kombination aus <strong>Grundtyp + Flügel</strong> (z. B. 4w3). Gefragt ist Typ und Flügel &ndash; die Instinktvariante (SE/SO/SX) spielt keine Rolle." },
  3: { label: "Enneagramm-Flashcards III", sub: "Experten · vollständiger Subtyp (Instinkt+Typ+Flügel)",
       rule: "Sie sehen ein Porträtfoto und vier Antwortmöglichkeiten, jede ein <strong>vollständiger Subtyp</strong> (z. B. SO1w9). Gefragt ist die exakte Kombination aus Instinktvariante, Typ und Flügel." },
};

let _flashState = null;
let _flashLastLevel = 1;

function _flashBestKey(level) { return "kompass:flashBest:" + level; }
function _flashSaveBest(level, score) {
  try {
    const prev = parseInt(localStorage.getItem(_flashBestKey(level)) || "0", 10);
    if (score > prev) localStorage.setItem(_flashBestKey(level), String(score));
  } catch (e) {}
}
function _flashGetBest(level) {
  try { return parseInt(localStorage.getItem(_flashBestKey(level)) || "0", 10); } catch (e) { return 0; }
}

function _flashRerender() {
  if (location.hash === "#enneagramm-flashcards") { render(); } else { location.hash = "enneagramm-flashcards"; }
}

async function _flashPickQuestion(level) {
  const pools = _memoryBuildPools(level);
  const keys = _memoryShuffle(Object.keys(pools));
  for (const correctKey of keys) {
    const found = await _memoryFindValidPortrait(_memoryShuffle(pools[correctKey]), new Set());
    if (!found) continue;
    const otherKeys = _memoryShuffle(Object.keys(pools).filter(k => k !== correctKey)).slice(0, 3);
    if (otherKeys.length < 3) continue;
    const options = _memoryShuffle([correctKey, ...otherKeys]);
    return { portrait: found, correctKey, options };
  }
  return null;
}

async function _flashNextRound() {
  const st = _flashState;
  if (!st) return;
  st.round += 1;
  if (st.round > FLASH_TOTAL_ROUNDS) {
    st.phase = "gameOver";
    _flashSaveBest(st.level, st.score);
    _flashRerender();
    return;
  }
  st.phase = "loading";
  _flashRerender();
  const q = await _flashPickQuestion(st.level);
  if (_flashState !== st) return;
  if (!q) { st.phase = "gameOver"; _flashRerender(); return; }
  st.question = q;
  st.answered = false;
  st.selectedKey = null;
  st.phase = "question";
  _flashRerender();
}

window._flashStart = function (level) {
  const lvl = FLASH_LEVEL_META[level] ? level : 1;
  _flashLastLevel = lvl;
  _flashState = { level: lvl, phase: "loading", round: 0, score: 0, question: null, answered: false, selectedKey: null };
  _flashNextRound();
};

window._flashSwitchLevel = function (level) {
  const lvl = FLASH_LEVEL_META[level] ? level : 1;
  _flashLastLevel = lvl;
  _flashState = null;
  _flashRerender();
};

window._flashAnswer = function (key) {
  const st = _flashState;
  if (!st || st.phase !== "question" || st.answered) return;
  st.answered = true;
  st.selectedKey = key;
  if (key === st.question.correctKey) st.score += 1;
  _flashRerender();
};

window._flashNextRound = function () { _flashNextRound(); };
window._flashRestart = function () {
  const lvl = _flashState ? _flashState.level : 1;
  window._flashStart(lvl);
};

function _flashLevelSwitcher(currentLevel) {
  const items = [1,2,3].map(l => {
    const active = l === currentLevel;
    return active
      ? `<span class="mem-level-pill mem-level-pill--active">${l===1?"I":l===2?"II":"III"}</span>`
      : `<a href="javascript:void(0)" class="mem-level-pill" onclick="window._flashSwitchLevel(${l})">${l===1?"I":l===2?"II":"III"}</a>`;
  }).join("");
  return `<div class="mem-level-switcher"><span class="mem-level-switcher-label">Stufe:</span>${items}</div>`;
}

function _flashStyles() {
  return `
    <style>
      .mem-level-switcher { display:flex; align-items:center; justify-content:center; gap:0.4rem; max-width:420px; margin:0 auto 0.8rem; font-size:0.8rem; }
      .mem-level-switcher-label { color:var(--muted); margin-right:0.2rem; }
      .mem-level-pill { display:inline-flex; align-items:center; justify-content:center; min-width:1.8rem; padding:0.2rem 0.5rem; border-radius:99px; border:1.5px solid var(--line,var(--border)); color:var(--muted); text-decoration:none; font-weight:600; cursor:pointer; }
      .mem-level-pill:hover { border-color:var(--copper); color:var(--copper); }
      .mem-level-pill--active { background:var(--copper,#a5603d); border-color:var(--copper,#a5603d); color:#fff; cursor:default; }
      .flash-rule-box { background:color-mix(in srgb, var(--copper) 8%, var(--paper)); border:1px solid var(--copper); border-radius:12px; padding:1rem 1.2rem; margin:0 0 1.4rem; font-size:0.9rem; line-height:1.55; }
      .flash-rule-box-label { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.05em; color:var(--copper); font-weight:700; margin:0 0 0.4rem; }
      .flash-photo-wrap { max-width:320px; margin:1.2rem auto; border-radius:14px; overflow:hidden; border:1px solid var(--line,var(--border)); aspect-ratio:1/1; }
      .flash-photo-wrap img { width:100%; height:100%; object-fit:cover; display:block; animation:flashPhotoIn .6s ease-out; }
      @keyframes flashPhotoIn { 0%{ filter:blur(13px); opacity:.2; } 100%{ filter:blur(0); opacity:1; } }
      .flash-options { display:grid; grid-template-columns:1fr 1fr; gap:0.7rem; max-width:420px; margin:1.2rem auto 0; }
      .flash-opt { padding:0.85rem 0.6rem; border-radius:10px; border:2px solid var(--line,var(--border)); background:var(--card,var(--paper)); font-size:0.95rem; font-weight:600; cursor:pointer; font-family:inherit; color:var(--ink); text-align:center; }
      .flash-opt:hover { border-color:var(--copper); }
      .flash-opt--correct { border-color:#3a9552; background:color-mix(in srgb, #3a9552 14%, var(--paper)); color:#3a9552; }
      .flash-opt--wrong { border-color:#c0392b; background:color-mix(in srgb, #c0392b 14%, var(--paper)); color:#c0392b; }
      .flash-opt[disabled] { cursor:default; }
      .flash-hud { display:flex; justify-content:space-between; align-items:baseline; max-width:420px; margin:0 auto 0.6rem; font-size:0.85rem; color:var(--muted); }
      .flash-hud strong { color:var(--ink); }
      .flash-feedback { text-align:center; max-width:420px; margin:1.2rem auto 0; }
      .flash-feedback p { margin:0 0 0.9rem; font-size:0.95rem; }
      .flash-name-reveal { background:var(--card,var(--paper)); border:1px solid var(--line,var(--border)); border-radius:10px; padding:0.7rem 1rem; margin:0 0 1rem; font-size:0.92rem; }
      .flash-btn { background:var(--copper,#a5603d); color:#fff; border:none; padding:0.75rem 2rem; border-radius:24px; font-size:0.95rem; font-family:inherit; cursor:pointer; font-weight:600; }
      .flash-explore-hint { font-size:0.78rem; color:var(--muted); text-align:center; margin:0.6rem 0 0; }
    </style>
  `;
}

function _flashIntroScreen(level) {
  const meta = FLASH_LEVEL_META[level];
  const best = _flashGetBest(level);
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_flashLevelSwitcher(level)}
        <p class="psycho-intro">Ein Porträtfoto, vier Antwortmöglichkeiten &ndash; sofortiges Feedback, 10 Fragen pro Runde. Anders als beim Memory geht es hier ums schnelle Wiedererkennen, nicht ums Merken von Positionen.</p>
        <div class="flash-rule-box">
          <p class="flash-rule-box-label">Wonach wird in dieser Stufe gefragt?</p>
          <p style="margin:0;">${meta.rule}</p>
        </div>
        ${best > 0 ? `<p style="text-align:center;color:var(--muted);font-size:0.9rem;margin-bottom:1.2rem;">Ihre Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${FLASH_TOTAL_ROUNDS}</strong></p>` : ""}
        <div style="text-align:center;">
          <button class="flash-btn" onclick="window._flashStart(${level})">Quiz starten &rarr;</button>
        </div>
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function _flashLoadingScreen() {
  const st = _flashState;
  const meta = FLASH_LEVEL_META[st.level];
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;padding-top:3rem;padding-bottom:5rem;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        <p style="color:var(--muted);margin-top:1.5rem;">Frage wird vorbereitet …</p>
      </div>
    </div>
  `);
}

function _flashQuestionScreen() {
  const st = _flashState;
  const meta = FLASH_LEVEL_META[st.level];
  const q = st.question;
  const optionsHtml = q.options.map(key => {
    const display = _flashKeyLabel(key, st.level);
    let cls = "flash-opt";
    let disabled = st.answered ? "disabled" : "";
    if (st.answered) {
      if (key === q.correctKey) cls += " flash-opt--correct";
      else if (key === st.selectedKey) cls += " flash-opt--wrong";
    }
    const onclick = st.answered ? "" : ` onclick="window._flashAnswer('${key}')"`;
    return `<button class="${cls}" ${disabled}${onclick}>${display}</button>`;
  }).join("");

  let feedback = "";
  if (st.answered) {
    const correct = st.selectedKey === q.correctKey;
    const isLast = st.round >= FLASH_TOTAL_ROUNDS;
    feedback = `
      <div class="flash-feedback">
        <p><strong>${correct ? "Richtig!" : "Leider falsch."}</strong></p>
        <div class="flash-name-reveal">${q.portrait.name} &ndash; <strong>${(q.portrait.subtyp||"").toUpperCase()}</strong></div>
        <button class="flash-btn" onclick="window._flashNextRound()">${isLast ? "Endergebnis &rarr;" : "Nächste Frage &rarr;"}</button>
      </div>
    `;
  }

  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_flashLevelSwitcher(st.level)}
        <div class="flash-hud">
          <span>Frage <strong>${st.round}</strong> / ${FLASH_TOTAL_ROUNDS}</span>
          <span>Punkte: <strong>${st.score}</strong></span>
        </div>
        <div class="flash-photo-wrap"><img src="${q.portrait.img}" alt="" /></div>
        <p style="text-align:center;color:var(--muted);font-size:0.85rem;">${st.level === 1 ? "Welcher Grundtyp ist das?" : st.level === 2 ? "Welcher Grundtyp + Flügel ist das?" : "Welcher Subtyp ist das?"}</p>
        <div class="flash-options">${optionsHtml}</div>
        ${feedback}
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function _flashKeyLabel(key, level) {
  if (level === 1) return "Typ " + key.slice(1);
  if (level === 2) { const m = key.match(/^T(\d)W(\d)$/); return m ? (m[1] + "w" + m[2]) : key; }
  const m = key.match(/^(SE|SO|SX)(\d)W?(\d)?$/);
  return m ? (m[1] + m[2] + (m[3] ? "w" + m[3] : "")) : key;
}

function _flashGameOverScreen() {
  const st = _flashState;
  const meta = FLASH_LEVEL_META[st.level];
  const best = _flashGetBest(st.level);
  const pct = Math.round((st.score / FLASH_TOTAL_ROUNDS) * 100);
  let msg;
  if (pct >= 90) msg = "Außergewöhnlich &ndash; ein sehr geschulter Blick für Blickqualitäten!";
  else if (pct >= 70) msg = "Sehr gut! Die Gesichter der Subtypen prägen sich bei Ihnen schon deutlich ein.";
  else if (pct >= 40) msg = "Solide Runde &ndash; mit mehr Übung wird der Blick noch sicherer.";
  else msg = "Ein Anfang &ndash; das Erkennen von Blickqualitäten braucht Übung. Nochmal versuchen?";
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${st.score} von ${FLASH_TOTAL_ROUNDS} richtig</h1>
        ${_flashLevelSwitcher(st.level)}
        <p style="color:var(--muted);margin:0 0 0.8rem;">${pct}&thinsp;%</p>
        <p style="max-width:420px;margin:0 auto 1rem;">${msg}</p>
        <p style="color:var(--muted);font-size:0.9rem;margin-bottom:2rem;">Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${FLASH_TOTAL_ROUNDS}</strong></p>
        <button class="flash-btn" onclick="window._flashRestart()">Neue Runde &rarr;</button>
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function enneagrammFlashcardsPage() {
  if (!_flashState) return _flashIntroScreen(_flashLastLevel);
  if (_flashState.phase === "loading") return _flashLoadingScreen();
  if (_flashState.phase === "gameOver") return _flashGameOverScreen();
  return _flashQuestionScreen();
}

