        {n:3,label:"Skrupelloser Tyrann"}, {n:2,label:"Allm\u00e4chtiger Gr\u00f6\u00dfenwahnsinniger"}, {n:1,label:"Gewaltt\u00e4tiger Zerst\u00f6rer"}
